import java.util.*;
interface PaymentMethod{boolean processPayment(double amount);}class CreditCardPayment implements PaymentMethod{public boolean processPayment(double a){System.out.println("Credit Card payment successful");return true;}}class PayPalPayment implements PaymentMethod{public boolean processPayment(double a){System.out.println("PayPal payment failed");return false;}}class Product{String name;double price;Product(String n,double p){name=n;price=p;}}
class Order{String customer;List<Product> items=new ArrayList<>();String status="Pending";Order(String c){customer=c;}void addProduct(Product p){items.add(p);}void pay(PaymentMethod m){if(items.isEmpty()){System.out.println("Cannot pay for empty order");return;}double total=0;for(Product p:items)total+=p.price;if(m.processPayment(total))status="Paid";System.out.println("Order status: "+status);}}
public class PaymentProcessingSystem{public static void main(String[] args){Order a=new Order("Customer X");a.addProduct(new Product("Product A",100));a.addProduct(new Product("Product B",50));a.pay(new CreditCardPayment());Order b=new Order("Customer Y");b.pay(new CreditCardPayment());Order c=new Order("Customer Z");c.addProduct(new Product("Product C",200));c.pay(new PayPalPayment());}}